export interface Contact {
  givenName: string;
  familyName: string;
}

export class Member implements Contact {
  readonly displayName: string;

  constructor(
    public readonly givenName: string,
    public readonly middleCode: string,
    public readonly familyName: string,
  ) {
    this.displayName = [givenName, middleCode, familyName]
      .filter((part) => part.length > 0)
      .join(" ");
  }
}

export function welcome(contact: Contact): string {
  return `Welcome, ${contact.givenName} ${contact.familyName}.`;
}

export class TurnOrder {
  private readonly names: string[];
  private offset = 0;

  constructor(names: readonly string[]) {
    this.names = [...names];
  }

  rotate(steps: number): void {
    if (!Number.isFinite(steps) || !Number.isInteger(steps)) {
      throw new RangeError("steps must be a finite integer");
    }
    if (this.names.length === 0) return;

    this.offset = (this.offset + steps) % this.names.length;
  }

  current(): string | undefined {
    return this.names.length === 0 ? undefined : this.names[this.offset];
  }

  snapshot(): string[] {
    return this.names.map(
      (_, index) => this.names[(this.offset + index) % this.names.length],
    );
  }
}

export function listWelcomes(order: TurnOrder, members: readonly Member[]): string[] {
  return order.snapshot().flatMap((name) => {
    const member = members.find((candidate) => candidate.displayName === name);
    return member === undefined ? [] : [`Welcome, ${member.displayName}.`];
  });
}

