import { Member, TurnOrder, welcome, listWelcomes } from './solution';

function equal(actual: unknown, expected: unknown, label: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function ok(condition: boolean, label: string): void {
  if (!condition) throw new Error(label);
}

function throwsRange(action: () => void, label: string): void {
  try {
    action();
  } catch (error) {
    ok(error instanceof RangeError, `${label}: wrong error type`);
    ok((error as Error).message === 'steps must be a finite integer', `${label}: wrong message`);
    return;
  }
  throw new Error(`${label}: did not throw`);
}

const robin = new Member('Nico', '', 'Robin');
const law = new Member('Trafalgar', 'D.', 'Law');
ok(robin.givenName === 'Nico' && robin.middleCode === '' && robin.familyName === 'Robin', 'member fields');
ok(robin.displayName === 'Nico Robin', 'empty middle code adds no space');
ok(law.displayName === 'Trafalgar D. Law', 'middle code is included');
ok(welcome(robin) === 'Welcome, Nico Robin.', 'welcome contact');
ok(welcome({ givenName: 'Monkey D.', familyName: 'Luffy' }) === 'Welcome, Monkey D. Luffy.', 'welcome structural contact');

const names = ['Nico Robin', 'Trafalgar D. Law', 'Unknown'];
const order = new TurnOrder(names);
names[0] = 'mutated';
ok(order.current() === 'Nico Robin', 'constructor input is copied');
equal(order.snapshot(), ['Nico Robin', 'Trafalgar D. Law', 'Unknown'], 'initial snapshot');

order.rotate(1);
ok(order.current() === 'Trafalgar D. Law', 'positive rotation');
equal(order.snapshot(), ['Trafalgar D. Law', 'Unknown', 'Nico Robin'], 'rotational snapshot');
order.rotate(-2);
ok(order.current() === 'Unknown', 'negative rotation wraps');
order.rotate(6);
ok(order.current() === 'Unknown', 'full-cycle rotation');

const snapshot = order.snapshot();
snapshot[0] = 'changed';
ok(order.current() === 'Unknown', 'snapshot is defensive');
equal(order.snapshot(), ['Unknown', 'Nico Robin', 'Trafalgar D. Law'], 'snapshot does not change state');

throwsRange(() => order.rotate(0.5), 'fractional steps');
throwsRange(() => order.rotate(Number.POSITIVE_INFINITY), 'infinite steps');
throwsRange(() => order.rotate(Number.NaN), 'NaN steps');

const empty = new TurnOrder([]);
ok(empty.current() === undefined, 'empty current');
empty.rotate(-100);
equal(empty.snapshot(), [], 'empty rotation does nothing');

const duplicateOrder = new TurnOrder(['Nico Robin', 'Missing', 'Nico Robin', 'Trafalgar D. Law']);
const members = Object.freeze([robin, law]);
equal(listWelcomes(duplicateOrder, members), [
  'Welcome, Nico Robin.',
  'Welcome, Nico Robin.',
  'Welcome, Trafalgar D. Law.',
], 'welcomes follow order, omit missing, and preserve duplicates');
equal(duplicateOrder.snapshot(), ['Nico Robin', 'Missing', 'Nico Robin', 'Trafalgar D. Law'], 'listWelcomes does not rotate order');
ok(members[0] === robin && members[1] === law, 'listWelcomes does not mutate members');

